    public void onClick(View v) {
        switch (v.getId()) {
            case R.id.rtglebutton2 /* 2131034126 */:
                this.msgTextView.setText("Insert 2 known values.");
                this.sideA.setText("");
                this.sideB.setText("");
                this.sideC.setText("");
                this.angleA.setText("");
                break;
            case R.id.rtglebutton1 /* 2131034127 */:
                try {
                    DecimalFormat df = new DecimalFormat("#.########");
                    double r = 0.0d;
                    double p = 0.0d;
                    double i = 0.0d;
                    double e = 0.0d;
                    int count = 0;
                    String msg = "Your inputs: ";
                    String a = this.sideA.getText().toString().trim();
                    if (!a.equals("")) {
                        count = 0 + 1;
                        msg = String.valueOf("Your inputs: ") + "Ohms & ";
                        r = Double.parseDouble(a);
                    }
                    String b = this.sideB.getText().toString().trim();
                    if (!b.equals("")) {
                        count++;
                        msg = String.valueOf(msg) + "Watts & ";
                        p = Double.parseDouble(b);
                    }
                    String c = this.sideC.getText().toString().trim();
                    if (!c.equals("") && count != 2) {
                        count++;
                        i = Double.parseDouble(c);
                        msg = String.valueOf(msg) + "Amps & ";
                    }
                    String aa = this.angleA.getText().toString().trim();
                    if (!aa.equals("") && count != 2) {
                        count++;
                        e = Double.parseDouble(aa);
                        msg = String.valueOf(msg) + "Volts & ";
                    }
                    if (count == 2) {
                        this.msgTextView.setText(msg.substring(0, msg.length() - 3));
                        if (r != 0.0d && p != 0.0d) {
                            double i2 = Math.sqrt(p / r);
                            Math.asin(r / i2);
                            this.sideC.setText(df.format(i2));
                            this.angleA.setText(df.format(i2 * r));
                            break;
                        } else if (r != 0.0d && i != 0.0d) {
                            double p2 = Math.pow(i, 2.0d) * r;
                            this.sideB.setText(df.format(p2));
                            this.angleA.setText(df.format(p2 / i));
                            break;
                        } else if (r != 0.0d && e != 0.0d) {
                            double i3 = e / r;
                            double p3 = e * i3;
                            this.sideB.setText(df.format(p3));
                            this.sideC.setText(df.format(i3));
                            break;
                        } else if (p != 0.0d && i != 0.0d) {
                            double e2 = p / i;
                            double r2 = e2 / i;
                            this.sideA.setText(df.format(r2));
                            this.angleA.setText(df.format(e2));
                            break;
                        } else if (p != 0.0d && e != 0.0d) {
                            double i4 = p / e;
                            double r3 = e / i4;
                            this.sideA.setText(df.format(r3));
                            this.sideC.setText(df.format(i4));
                            break;
                        } else if (i != 0.0d && e != 0.0d) {
                            double r4 = e / i;
                            double p4 = e * i;
                            this.sideA.setText(df.format(r4));
                            this.sideB.setText(df.format(p4));
                            break;
                        }
                    } else {
                        Toast.makeText(this, "Two (non-zero) entries are needed.", 1).show();
                        break;
                    }
                } catch (Exception e3) {
                    Toast.makeText(getBaseContext(), "Please Enter Valid Numbers.", 0).show();
                    return;
                }
                break;
        }
    }

